    if (achieved != NULL) { achieved->x = 0.0; achieved->y = 0.0; achieved->z = 0.0; }
    if (residual != NULL) { residual->x = 0.0; residual->y = 0.0; residual->z = 0.0; }
    if (mask != NULL) { *mask = 0U; }
    return ADCS_E_RANGE;
}

for (i = 0U; i < 3U; i++) {
    if (adcs_vec3_normalize(&axes[i], ADCS_EPS_NORM, &u[i]) != ADCS_OK) {
        if (wheel_torque != NULL) { wheel_torque[0] = 0.0; wheel_torque[1] = 0.0; wheel_torque[2] = 0.0; }
        if (achieved != NULL) { achieved->x = 0.0; achieved->y = 0.0; achieved->z = 0.0; }
        if (residual != NULL) { residual->x = 0.0; residual->y = 0.0; residual->z = 0.0; }
        if (mask != NULL) { *mask = 0U; }
        return ADCS_E_DEGENERATE;
    }
}

for (i = 0U; i < 3U; i++) {
    for (j = i + 1U; j < 3U; j++) {
        d = adcs_vec3_dot(&u[i], &u[j]);
        if (fabs(d) > 1e-10) {
            if (wheel_torque != NULL) { wheel_torque[0] = 0.0; wheel_torque[1] = 0.0; wheel_torque[2] = 0.0; }
            if (achieved != NULL) { achieved->x = 0.0; achieved->y = 0.0; achieved->z = 0.0; }
            if (residual != NULL) { residual->x = 0.0; residual->y = 0.0; residual->z = 0.0; }
            if (mask != NULL) { *mask = 0U; }
            return ADCS_E_DEGENERATE;
        }
    }
}

*mask = 0U;
for (i = 0U; i < 3U; i++) {
    adcs_actuator_limit_t lim_cfg;
    double val = -adcs_vec3_dot(&u[i], request);
    lim_cfg.min_value = -torque_limit_nm;
    lim_cfg.max_value = torque_limit_nm;
    lim_cfg.max_slew_per_s = 0.0;
    (void)adcs_limit_scalar(val, &lim_cfg, &lim);
    tau[i] = lim;
    wheel_torque[i] = lim;
    if (lim != val) {
        *mask |= (uint32_t)(1U << i);
    }
}

achieved_sum.x = 0.0;
achieved_sum.y = 0.0;
achieved_sum.z = 0.0;
for (i = 0U; i < 3U; i++) {
    adcs_vec3_t term = adcs_vec3_scale(&u[i], tau[i]);
    achieved_sum.x += term.x;
    achieved_sum.y += term.y;
    achieved_sum.z += term.z;
}
*achieved = achieved_sum;
*residual = adcs_vec3_sub(request, &achieved_sum);

return ADCS_OK;
